/* =========================================================
   ZUPER LED - FINAL MOBILE/TABLET MENU
========================================================= */

document.addEventListener("DOMContentLoaded", function () {

    /* =====================================================
       CSS
    ====================================================== */

    const style = document.createElement("style");

    style.innerHTML = `

    /* =====================================================
       HIDE DESKTOP MENU BELOW 1025
    ====================================================== */

    @media (max-width:1024px){

        /* Hide Desktop Navigation */
        .elementor-element-18ab3b1{
            display:none !important;
        }

        /* Hide Existing Search */
        .elementor-element-447b0f8{
            display:none !important;
        }

        /* Hide Existing Mobile Menus */
        .elementor-element-ac8166a,
        .elementor-element-948ccb3{
            display:none !important;
        }

        .sasi-menu-mobile,
        #mmenu-wrapper,
        #mmenu-toggle{
            display:none !important;
        }

    }

    /* =====================================================
       SHOW CUSTOM MENU
    ====================================================== */

    .custom-zuper-mobile-menu-wrapper{
        display:none;
    }

    @media (max-width:1024px){

        .custom-zuper-mobile-menu-wrapper{
            display:flex !important;
            align-items:center;
            justify-content:flex-end;
            width:100%;
            position:relative;
            z-index:99999;
        }

    }

    /* =====================================================
       TARGET CONTAINER FIX
    ====================================================== */

    @media (max-width:1024px){

        .elementor-element-908d6f4{
            width:auto !important;
            flex:1 !important;
            display:flex !important;
            justify-content:flex-end !important;
            align-items:center !important;
        }

    }

    /* =====================================================
       HAMBURGER
    ====================================================== */

    .custom-zuper-hamburger{
        width:40px;
        height:40px;
        background:#dbfb04;
        border-radius:8px;
        display:flex;
        flex-direction:column;
        justify-content:center;
        align-items:center;
        gap:4px;
        cursor:pointer;
        transition:0.3s ease;
    }

    .custom-zuper-hamburger:hover{
        transform:scale(1.05);
    }

    .custom-zuper-hamburger span{
        width:18px;
        height:2px;
        background:#090d16;
        border-radius:20px;
    }

    /* Mobile Smaller */

    @media (max-width:767px){

        .custom-zuper-hamburger{
            width:36px;
            height:36px;
        }

        .custom-zuper-hamburger span{
            width:16px;
        }

    }

    /* =====================================================
       OVERLAY
    ====================================================== */

    .custom-zuper-overlay{
        position:fixed;
        inset:0;
        background:rgba(0,0,0,0.55);
        opacity:0;
        visibility:hidden;
        transition:0.3s ease;
        z-index:999998;
    }

    .custom-zuper-overlay.active{
        opacity:1;
        visibility:visible;
    }

    /* =====================================================
       SIDEBAR
    ====================================================== */

    .custom-zuper-sidebar{
        position:fixed;
        top:0;
        right:-100%;
        width:320px;
        max-width:90%;
        height:100vh;
        background:#090d16;
        z-index:999999;
        transition:0.4s ease;
        overflow-y:auto;
        padding:30px;
        box-shadow:-10px 0 30px rgba(0,0,0,0.35);
    }

    .custom-zuper-sidebar.active{
        right:0;
    }

    @media (max-width:767px){

        .custom-zuper-sidebar{
            width:280px;
            padding:24px;
        }

    }

    /* =====================================================
       CLOSE BUTTON
    ====================================================== */

    .custom-zuper-close{
        display:flex;
        justify-content:flex-end;
        margin-bottom:25px;
    }

    .custom-zuper-close button{
        background:none;
        border:none;
        color:#ffffff;
        font-size:34px;
        cursor:pointer;
        line-height:1;
    }

    /* =====================================================
       MENU
    ====================================================== */

    .custom-zuper-sidebar ul{
        list-style:none;
        margin:0;
        padding:0;
    }

    .custom-zuper-sidebar ul li{
        border-bottom:1px solid rgba(255,255,255,0.08);
    }

    .custom-zuper-sidebar ul li a{
        color:#ffffff;
        text-decoration:none;
        display:flex;
        justify-content:space-between;
        align-items:center;
        padding:16px 0;
        font-size:16px;
        font-weight:500;
        transition:0.3s ease;
    }

    .custom-zuper-sidebar ul li a:hover{
        color:#dbfb04;
        padding-left:6px;
    }

    /* =====================================================
       SUBMENU
    ====================================================== */

    .custom-zuper-sidebar .sub-menu{
        display:none;
        padding-left:14px;
        padding-bottom:10px;
    }

    .custom-zuper-sidebar .sub-menu li{
        border:none;
    }

    .custom-zuper-sidebar .sub-menu li a{
        font-size:14px;
        color:#d9d9d9;
        padding:10px 0;
    }

    /* =====================================================
       TOGGLE
    ====================================================== */

    .custom-dropdown-toggle{
        color:#dbfb04;
        font-size:18px;
        margin-left:10px;
        cursor:pointer;
        font-weight:bold;
    }

    `;

    document.head.appendChild(style);

    /* =====================================================
       TARGET CONTAINER
    ====================================================== */

    const targetContainer = document.querySelector(
        ".elementor-element-908d6f4"
    );

    if (!targetContainer) return;

    /* =====================================================
       DESKTOP MENU
    ====================================================== */

    const desktopMenu = document.querySelector("#primary-menu");

    if (!desktopMenu) return;

    /* =====================================================
       CREATE HAMBURGER
    ====================================================== */

    const wrapper = document.createElement("div");

    wrapper.className = "custom-zuper-mobile-menu-wrapper";

    wrapper.innerHTML = `
        <div class="custom-zuper-hamburger">
            <span></span>
            <span></span>
            <span></span>
        </div>
    `;

    targetContainer.appendChild(wrapper);

    /* =====================================================
       OVERLAY
    ====================================================== */

    const overlay = document.createElement("div");

    overlay.className = "custom-zuper-overlay";

    document.body.appendChild(overlay);

    /* =====================================================
       SIDEBAR
    ====================================================== */

    const sidebar = document.createElement("div");

    sidebar.className = "custom-zuper-sidebar";

    sidebar.innerHTML = `
        <div class="custom-zuper-close">
            <button>&times;</button>
        </div>

        <nav class="custom-zuper-nav">
            ${desktopMenu.outerHTML}
        </nav>
    `;

    document.body.appendChild(sidebar);

    /* =====================================================
       OPEN
    ====================================================== */

    const hamburger = wrapper.querySelector(
        ".custom-zuper-hamburger"
    );

    hamburger.addEventListener("click", function () {

        sidebar.classList.add("active");
        overlay.classList.add("active");

        document.body.style.overflow = "hidden";

    });

    /* =====================================================
       CLOSE
    ====================================================== */

    function closeMenu(){

        sidebar.classList.remove("active");
        overlay.classList.remove("active");

        document.body.style.overflow = "";

    }

    overlay.addEventListener("click", closeMenu);

    sidebar
        .querySelector(".custom-zuper-close button")
        .addEventListener("click", closeMenu);

    /* =====================================================
       SUBMENUS
    ====================================================== */

    const items = sidebar.querySelectorAll(
        ".menu-item-has-children"
    );

    items.forEach(function(item){

        const link = item.querySelector("a");
        const submenu = item.querySelector(".sub-menu");

        if(!submenu) return;

        const toggle = document.createElement("span");

        toggle.className = "custom-dropdown-toggle";
        toggle.innerHTML = "+";

        link.appendChild(toggle);

        toggle.addEventListener("click", function(e){

            e.preventDefault();
            e.stopPropagation();

            if(submenu.style.display === "block"){

                submenu.style.display = "none";
                toggle.innerHTML = "+";

            }else{

                submenu.style.display = "block";
                toggle.innerHTML = "−";

            }

        });

    });

});